from pysat.solvers import Glucose3
from pysat.card import *
import itertools

n = 13
num_edges = n * (n - 1) // 2  # 78

def get_edge_index(i, j):
    idx = 0
    for a in range(i):
        idx += (n - 1 - a)
    idx += (j - i - 1)
    return idx

def get_edge_from_index(idx):
    current = 0
    for i in range(n):
        for j in range(i+1, n):
            if current == idx:
                return (i, j)
            current += 1
    return None

# Build SAT formula
# Variable x_e = 1 means edge e is blue, x_e = 0 means edge e is red
# For each 4-clique, we need at least one red edge AND at least one blue edge

solver = Glucose3()

# Add constraints for no monochromatic K4
# For each set of 4 vertices, the 6 edges among them cannot all be 0 or all be 1
for vertices in itertools.combinations(range(n), 4):
    edges = []
    for i in range(4):
        for j in range(i+1, 4):
            e = get_edge_index(vertices[i], vertices[j])
            edges.append(e + 1)  # 1-indexed for SAT

    # Not all red (not all 0): at least one must be 1
    solver.add_clause(edges)

    # Not all blue (not all 1): at least one must be 0
    solver.add_clause([-e for e in edges])

# Add fixed assignments
fixed = {
    3: 1, 6: 0, 13: 0, 19: 0, 27: 0, 34: 1, 35: 0, 43: 1, 
    56: 1, 63: 0, 65: 1, 74: 0, 75: 0, 76: 0, 77: 0
}

for idx, val in fixed.items():
    if val == 1:
        solver.add_clause([idx + 1])
    else:
        solver.add_clause([-(idx + 1)])

print("Solving...")
if solver.solve():
    model = solver.get_model()
    solution = [0] * num_edges
    for i in range(num_edges):
        if model[i] > 0:
            solution[i] = 1
        else:
            solution[i] = 0

    print("Solution found!")
    print(solution)

    # Verify solution
    def verify_solution(sol):
        for vertices in itertools.combinations(range(n), 4):
            edges = []
            for i in range(4):
                for j in range(i+1, 4):
                    e = get_edge_index(vertices[i], vertices[j])
                    edges.append(sol[e])
            if all(e == 0 for e in edges):
                print(f"Red K4 found at vertices {vertices}")
                return False
            if all(e == 1 for e in edges):
                print(f"Blue K4 found at vertices {vertices}")
                return False
        return True

    if verify_solution(solution):
        print("Solution verified!")
    else:
        print("Solution verification failed!")
else:
    print("UNSATISFIABLE")

solver.delete()
